cases.bad:
onStatusCycle: () => cycleStatus(state),
onDefinitionToggle: (id, selected) => toggleDefinition(state, id, selected),
// Both return new state, but the callback ignores it.
// cycleStatus also calls rerender(state) before updating, so the badge stays stale.

function rerender(state) {
  const container = state.shell.getContainer();
  renderPopupContent(container, state.currentResult, state.currentStatus, state.definitionSelection, callbacks);
  // renderPopupContent clears container, so appended candidates are lost.
}

cases.good:
onStatusCycle: () => { state = cycleStatus(state); },
onDefinitionToggle: (id, selected) => { state = toggleDefinition(state, id, selected); },

function cycleStatus(state) {
  const newStatus = nextStatus(state.currentStatus);
  const newState = { ...state, currentStatus: newStatus };
  rerender(newState);
  return newState;
}

function rerender(state) {
  const list = getOrCreateCandidateList(container);
  const existing = Array.from(list.children);
  const winner = existing.shift();
  if (winner) winner.remove();
  renderCandidate(list, state.currentResult, state.currentStatus, state.definitionSelection, callbacks, true);
  existing.forEach((c) => list.appendChild(c));
  renderWinnerToolbar(state, container);
}
